from collections import deque
masks={
'T1':['0110','1000','1001','0011'],
'T2':['0110','0001','1001','0110'],
'T3':['1100','1001','0001','0000'],
'T4':['0000','1001','0001','0000'],
'T5':['1111','1001','1001','0110'],
'T6':['0110','1000','1001','0011'],
}
def comps(a,diag=False):
  pts={(r,c) for r,row in enumerate(a) for c,v in enumerate(row) if v=='1'}
  n=0
  while pts:
    n+=1; q=[pts.pop()]
    while q:
      r,c=q.pop()
      for dr in (-1,0,1):
       for dc in (-1,0,1):
        if not dr and not dc: continue
        if not diag and abs(dr)+abs(dc)!=1: continue
        p=(r+dr,c+dc)
        if p in pts: pts.remove(p);q.append(p)
  return n
for k,a in masks.items(): print(k, sum(x.count('1') for x in a), comps(a),comps(a,True))
